%%\ SIMULACIÓN DE CONTROL DE CARGAS Y BATERÍAS EN MICRO-RED (24 HORAS)
% Autor : Hermes Antonio Pérez Cano
% Curso : Software para Ingeniería (203036) - UNAD
% Reto  : 3 - Algoritmo de control y cargas (SIGE)
% Objetivo: evaluar hora por hora el balance energético de una micro-red
%           híbrida (solar + eólica), actualizar el estado de carga (SOC)
%           del banco de baterías y aplicar desconexión de cargas por
%           prioridad (Load Shedding) según el nivel de SOC.

clear; clc; close all;  % Limpia variables, consola y figuras para una ejecución reproducible

%%\ 1. CONFIGURACIÓN INICIAL DE VECTORES Y PARÁMETROS
% Vectores de 24 posiciones (una por hora) desarrollados en el Reto 2.
E_gen = [0, 0, 0, 0, 0, 2, 8, 15, 25, 35, 45, 50, 48, 40, 30, 20, 10, 3, 0, 0, 0, 0, 0, 0];  % Generación híbrida total (solar + eólica) en kWh por hora
E_dem = [12, 10, 10, 10, 12, 18, 22, 25, 20, 18, 18, 20, 22, 20, 18, 22, 25, 28, 25, 20, 16, 14, 12, 12]; % Demanda total (escuela + bombeo + alumbrado) en kWh por hora

Capacidad_bat = 100;  % Capacidad total del banco de baterías en kWh
SOC           = 50;  % Estado de carga inicial de seguridad en porcentaje (%)

SOC_MAX     = 100;  % Límite máximo de seguridad (evita sobrecarga)
SOC_MIN     = 0;  % Límite mínimo absoluto (evita vaciamiento profundo)
SOC_SEGURO  = 40;  % Umbral superior de la Ruta de Alerta (Ruta Segura si SOC > 40 %)
SOC_ALERTA  = 20;  % Umbral de la Ruta de Emergencia (Emergencia si SOC <= 20 %)

%%\ 2. INICIALIZACIÓN DE ESTRUCTURAS PARA EL REGISTRO DE RESULTADOS
SOC_historial    = zeros(1, 24);  % Vector que almacenará el SOC al cierre de cada hora
balance_historial = zeros(1, 24);  % Vector que almacenará el balance Egen - Edem de cada hora
estado_escuela   = cell(1, 24);  % Celdas con el estado de la escuela rural (prioridad crítica)
estado_bombeo    = cell(1, 24);  % Celdas con el estado del bombeo agrícola (prioridad media)
estado_alumbrado = cell(1, 24);  % Celdas con el estado del alumbrado público (prioridad baja)
ruta_historial   = cell(1, 24);  % Celdas con la ruta de operación aplicada en cada hora

%%\ 3. BUCLE DE SIMULACIÓN DE 24 HORAS
disp('--- INICIO DEL REPORTE DE CONTROL HORA POR HORA ---');  % Encabezado del reporte en la consola %[output:6b50b563]

for hora = 1:24  % Recorre secuencialmente las 24 horas del día %[output:group:1055d808]

    E_balance = E_gen(hora) - E_dem(hora);  % Balance energético de la hora: positivo = superávit, negativo = déficit

    if E_balance >= 0  % ESCENARIO DE SUPERÁVIT (Egen >= Edem)
        excedente = E_balance;  % Excedente energético (Egen - Edem) en kWh
        SOC = SOC + (excedente / Capacidad_bat) * 100;  % Carga: SOC nuevo = SOC actual + (Excedente / Capacidad) x 100
        if SOC > SOC_MAX  % Verifica si la carga supera el límite de seguridad
            SOC = SOC_MAX;  % Limita el SOC al 100 % para proteger los equipos
        end
        ruta      = 'Superávit';  % Etiqueta de la ruta aplicada en esta hora
        escuela   = 'ACTIVA';  % Escuela rural permanece energizada
        bombeo    = 'ACTIVO';  % Bombeo agrícola permanece activo (operación nominal)
        alumbrado = 'ACTIVO';  % Alumbrado público permanece activo (operación nominal)

    else  % ESCENARIO DE DÉFICIT (Egen < Edem)
        faltante = abs(E_balance);  % Faltante energético (Edem - Egen) en kWh, siempre positivo
        SOC = SOC - (faltante / Capacidad_bat) * 100;  % Descarga: SOC nuevo = SOC actual - (Faltante / Capacidad) x 100
        if SOC < SOC_MIN  % Verifica si la descarga supera el límite mínimo
            SOC = SOC_MIN;  % Limita el SOC al 0 % para evitar vaciamiento profundo
        end

        if SOC > SOC_SEGURO  % RUTA SEGURA: SOC > 40 %
            ruta      = 'Segura';  % Etiqueta de la ruta
            escuela   = 'ACTIVA';  % Prioridad crítica: energizada
            bombeo    = 'ACTIVO';  % Prioridad media: activo
            alumbrado = 'ACTIVO';  % Prioridad baja: activo

        elseif SOC > SOC_ALERTA  % RUTA DE ALERTA: 20 % < SOC <= 40 %
            ruta      = 'Alerta';  % Etiqueta de la ruta
            escuela   = 'ACTIVA';  % Prioridad crítica: energizada
            bombeo    = 'ACTIVO';  % Prioridad media: activo
            alumbrado = 'APAGADO';  % Prioridad baja: se desconecta para reducir la demanda

        else  % RUTA DE EMERGENCIA: SOC <= 20 %
            ruta      = 'Emergencia';  % Etiqueta de la ruta
            escuela   = 'ACTIVA';  % Prioridad crítica: se mantiene energizada estrictamente
            bombeo    = 'APAGADO';  % Prioridad media: se desconecta
            alumbrado = 'APAGADO';  % Prioridad baja: se desconecta
        end
    end

    SOC_historial(hora)     = SOC;  % Guarda el SOC de la hora en el historial
    balance_historial(hora) = E_balance;  % Guarda el balance de la hora en el historial
    ruta_historial{hora}    = ruta;  % Guarda la ruta aplicada
    estado_escuela{hora}    = escuela;  % Guarda el estado de la escuela
    estado_bombeo{hora}     = bombeo;  % Guarda el estado del bombeo
    estado_alumbrado{hora}  = alumbrado;  % Guarda el estado del alumbrado

    fprintf(['Hora: %02d:00 | Gen: %5.1f kWh | Dem: %5.1f kWh | Balance: %+6.1f kWh | ' ... %[output:598454a9]
             'SOC: %5.1f%% | Ruta: %-10s | Escuela: %s | Bombeo: %s | Alumbrado: %s\n'], ... %[output:598454a9]
             hora, E_gen(hora), E_dem(hora), E_balance, SOC, ruta, escuela, bombeo, alumbrado);  % Reporte horario en consola %[output:598454a9]
end %[output:group:1055d808]

disp('--- FIN DE LA SIMULACIÓN ---');  % Cierre del reporte en la consola %[output:6cdb12c4]

%%\ 4. GRÁFICA DE COMPORTAMIENTO DEL SISTEMA (2 PANELES)
figure('Color', 'w', 'Position', [100, 100, 900, 500]);  % Crea la figura 1 con fondo blanco y tamaño definido %[output:420141ee]
subplot(2,1,1);  % Panel superior: generación vs demanda %[output:420141ee]
plot(1:24, E_gen, '-r', 'LineWidth', 2);  % Curva de generación híbrida (roja continua) %[output:420141ee]
hold on;  % Mantiene el gráfico para superponer la demanda %[output:420141ee]
plot(1:24, E_dem, '--b', 'LineWidth', 2);  % Curva de demanda total (azul discontinua) %[output:420141ee]
grid on;  % Activa la cuadrícula %[output:420141ee]
xlabel('Hora del Día');  % Etiqueta del eje horizontal %[output:420141ee]
ylabel('Energía (kWh)');  % Etiqueta del eje vertical %[output:420141ee]
title('Gestión Energética de la Micro-Red - 24 Horas');  % Título del panel %[output:420141ee]
legend('Generación Híbrida (E_{gen})', 'Demanda Total (E_{dem})', 'Location', 'northeast');  % Leyenda %[output:420141ee]
xlim([1 24]);  % Limita el eje horizontal a las 24 horas %[output:420141ee]

subplot(2,1,2);  % Panel inferior: evolución del SOC %[output:420141ee]
plot(1:24, SOC_historial, '-ok', 'LineWidth', 1.5, 'MarkerFaceColor', 'g');  % Curva del SOC con marcadores %[output:420141ee]
hold on;  % Mantiene el gráfico para dibujar los umbrales %[output:420141ee]
yline(SOC_SEGURO, '--r', 'Umbral Alerta (40%)', 'LineWidth', 1.2, 'LabelHorizontalAlignment', 'left');  % Línea del umbral de alerta %[output:420141ee]
yline(SOC_ALERTA, ':r', 'Umbral Emergencia (20%)', 'LineWidth', 1.2, 'LabelHorizontalAlignment', 'left');  % Línea del umbral de emergencia %[output:420141ee]
grid on;  % Activa la cuadrícula %[output:420141ee]
xlabel('Hora del Día');  % Etiqueta del eje horizontal %[output:420141ee]
ylabel('SOC (%)');  % Etiqueta del eje vertical %[output:420141ee]
title('Evolución del Estado de Carga de la Batería (SOC)');  % Título del panel %[output:420141ee]
ylim([-5 105]);  % Margen vertical para ver los límites 0 % y 100 % %[output:420141ee]
xlim([1 24]);  % Limita el eje horizontal a las 24 horas %[output:420141ee]

%%\ 5. GRÁFICA AVANZADA DE COMPORTAMIENTO DEL SISTEMA (3 PANELES)
figure('Color', 'w', 'Position', [50, 50, 950, 750]);  % Crea la figura 2 con fondo blanco y tamaño definido %[output:38e4e21f]

% --- PANEL 1: Generación vs Demanda ---
subplot(3,1,1);  % Panel superior %[output:38e4e21f]
plot(1:24, E_gen, '-ob', 'LineWidth', 2, 'MarkerFaceColor', 'b');  % Generación híbrida con marcadores %[output:38e4e21f]
hold on;  % Superpone la demanda %[output:38e4e21f]
plot(1:24, E_dem, '-rs', 'LineWidth', 1.5, 'MarkerFaceColor', 'r');  % Demanda total con marcadores %[output:38e4e21f]
grid on;  % Activa la cuadrícula %[output:38e4e21f]
xlabel('Hora del Día');  % Etiqueta del eje horizontal %[output:38e4e21f]
ylabel('Energía (kWh)');  % Etiqueta del eje vertical %[output:38e4e21f]
title('Gestión Energética: Generación Híbrida vs Demanda Total');  % Título del panel %[output:38e4e21f]
legend('Generación Híbrida', 'Demanda Total', 'Location', 'northeast');  % Leyenda %[output:38e4e21f]
xlim([1 24]);  % Limita el eje horizontal %[output:38e4e21f]

% --- PANEL 2: Dinámica de la batería y SOC ---
subplot(3,1,2);  % Panel central %[output:38e4e21f]
bar(1:24, balance_historial, 'FaceColor', [0.3 0.6 0.8]); % Barras del flujo de la batería (positivo = carga, negativo = descarga) %[output:38e4e21f]
hold on;  % Mantiene el gráfico para el eje secundario %[output:38e4e21f]
ylabel('Flujo Batería (kWh)');  % Etiqueta del eje izquierdo %[output:38e4e21f]
grid on;  % Activa la cuadrícula %[output:38e4e21f]
xlim([1 24]);  % Limita el eje horizontal %[output:38e4e21f]
yyaxis right;  % Activa el eje derecho para el SOC en porcentaje %[output:38e4e21f]
plot(1:24, SOC_historial, '-dm', 'LineWidth', 2, 'MarkerFaceColor', 'm');  % Curva del SOC %[output:38e4e21f]
yline(SOC_SEGURO, '--r', 'SoC Alerta (40%)', 'LineWidth', 1.2);  % Umbral de alerta %[output:38e4e21f]
yline(SOC_ALERTA, ':r', 'SoC Emergencia (20%)', 'LineWidth', 1.2);  % Umbral de emergencia %[output:38e4e21f]
ylabel('SoC (%)');  % Etiqueta del eje derecho %[output:38e4e21f]
ylim([-5 105]);  % Margen vertical del SOC %[output:38e4e21f]
title('Dinámica del Almacenamiento (BESS) y Estado de Carga');  % Título del panel %[output:38e4e21f]
legend('Flujo Batería', 'SoC (%)', 'Location', 'southwest');  % Leyenda %[output:38e4e21f]

% --- PANEL 3: Desglose de prioridad de cargas ---
subplot(3,1,3);  % Panel inferior %[output:38e4e21f]
% Matriz de potencias por nivel de prioridad (valores ilustrativos de cada carga en kW)
matriz_cargas = zeros(3, 24);  % Fila 1 = escuela, fila 2 = bombeo, fila 3 = alumbrado
for h = 1:24  % Recorre las 24 horas
    matriz_cargas(1, h) = 4;  % Escuela (prioridad alta): siempre activa, 4 kW de base
    if strcmp(estado_bombeo{h}, 'ACTIVO')  % Si el bombeo está activo en la hora h
        matriz_cargas(2, h) = 8;  % Bombeo (prioridad media): 8 kW
    end
    if strcmp(estado_alumbrado{h}, 'ACTIVO')  % Si el alumbrado está activo en la hora h
        matriz_cargas(3, h) = 6;  % Alumbrado (prioridad baja): 6 kW
    end
end
bar(1:24, matriz_cargas', 'stacked');  % Barras apiladas por nivel de prioridad %[output:38e4e21f]
grid on;  % Activa la cuadrícula %[output:38e4e21f]
xlabel('Hora del Día');  % Etiqueta del eje horizontal %[output:38e4e21f]
ylabel('Potencia (kW)');  % Etiqueta del eje vertical %[output:38e4e21f]
title('Desglose de Despacho de Demanda por Nivel de Prioridad');  % Título del panel %[output:38e4e21f]
legend({'Prioridad Alta (Escuela)', 'Prioridad Media (Bombeo)', 'Prioridad Baja (Alumbrado)'}, 'Location', 'northwest');  % Leyenda %[output:38e4e21f]
xlim([1 24]);  % Limita el eje horizontal %[output:38e4e21f]



